import{z as i,x as n,o as e,c as l,q as A,j as r,D as a,d as B,s,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"嵌入式安全","description":"","frontmatter":{"title":"嵌入式安全","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-security.md","filePath":"cs/emb-security.md","lastUpdated":1791413859000}'),d={name:"cs/emb-security.md"};function p(D,E,c,C,T,m){const t=n("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="嵌入式安全" tabindex="-1">嵌入式安全 <a class="header-anchor" href="#嵌入式安全" aria-label="Permalink to &quot;嵌入式安全&quot;">​</a></h1><div class="epigraph"><p>嵌入式攻击者的优势是物理：设备在他手里，示波器、探针、拆焊台都在他手里。防守的目标不是「攻不破」，而是让攻击的成本高于设备本身的价值。</p><footer>—— 据 NIST SP 800-193（平台固件恢复）；Mirai 事件后的 IoT 安全实践整理</footer></div><p><a href="/cs/emb-ota-updates">上一课</a>把更新通道打通了，但留下一笔欠账：镜像只验了完整性，没验来源——谁能往那条通道里写东西，谁就能给整个机队换上自己的固件。本课把嵌入式设备当成一个完整的攻击面来防守。与服务器安全的分野只有一个：这里的攻击者<strong>拿得到物理设备</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理在手意味着什么？SWD/JTAG 调试口两根线就能读写全部闪存；SPI 闪存夹上编程器夹，几分钟拷走完整镜像；板上的 <a href="/cs/emb-i2c-spi">I2C 与 SPI</a> 总线明文传输，示波器直接回放。再叠加软件侧的懒——出厂统一口令、永不更新的固件——就是 2016 年 Mirai 僵尸网络的配方：约六十万台摄像头与路由器被默认口令收编，砸瘫了半个美国东海岸的 DNS。缺口的形状因此清楚：设备需要一条<strong>从不可改写的起点出发的信任链</strong>、一个<strong>密钥的容身之处</strong>、以及<strong>出厂时对攻击面的收缩</strong>，三者都要在几百 KB 闪存的预算内完成。</p><h3 id="信任链与密钥的家" tabindex="-1">信任链与密钥的家 <a class="header-anchor" href="#信任链与密钥的家" aria-label="Permalink to &quot;信任链与密钥的家&quot;">​</a></h3><p>信任链的起点必须是攻击者改不了的东西： masked ROM 或一次性熔丝里的根公钥。芯片上电先跑 ROM 代码，验证引导加载器的签名，通过才移交；加载器再验证应用，应用再验证每一包 OTA 更新——<a href="/cs/secure-boot-chain">安全启动链</a>讲的逐级验签在 MCU 上落成同一结构，只是每一环都小得多。密钥的「家」按预算三选：最省的是 OTP eFuse，写进去了谁也读不出（只能比对）；好一些的是带 TrustZone-M 的芯片，把密钥隔离在安全世界；顶配是外挂安全元件，密钥根本不出那颗芯片。对称密钥用 AES-GCM 这类 <a href="/cs/aead-gcm-internals">AEAD</a> 同时拿机密性与真实性；非对称签名用于镜像与固件，因为验证端只需要公钥。</p><p><span class="marginnote">信任链可以想象成接力赛查证件：第一棒（ROM 代码）的身份证直接刻在芯片里改不了，他查验第二棒（引导加载器）的证件才交棒，第二棒再验第三棒（应用）。任何一棒拿不出上一棒签发的证件就不许上场——伪造整条链，等于要伪造根。</span></p>',8)),(e(),r(o,null,{default:a(()=>[s(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROM%5B%22ROM%20%E6%A0%B9%E4%BB%A3%E7%A0%81%EF%BC%9A%E6%A0%B9%E5%85%AC%E9%92%A5%E4%B8%8D%E5%8F%AF%E6%94%B9%E5%86%99%22%5D%20--%3E%20BL%5B%22%E9%AA%8C%E5%BC%95%E5%AF%BC%E5%8A%A0%E8%BD%BD%E5%99%A8%E7%AD%BE%E5%90%8D%22%5D%0A%20%20BL%20--%3E%20APP%5B%22%E9%AA%8C%E5%BA%94%E7%94%A8%E9%95%9C%E5%83%8F%E7%AD%BE%E5%90%8D%22%5D%0A%20%20APP%20--%3E%20OTA%5B%22%E9%AA%8C%E6%AF%8F%E5%8C%85%20OTA%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20OTA%20--%3E%20KEY%5B%22%E5%AF%86%E9%92%A5%E5%AD%98%E4%BA%8E%20OTP%20%E6%88%96%E5%AE%89%E5%85%A8%E5%85%83%E4%BB%B6%22%5D%0A%20%20KEY%20--%3E%20TLS%5B%22%E5%AF%B9%E5%A4%96%E9%80%9A%E4%BF%A1%E8%B5%B0%20AEAD%20%E5%8A%A0%E5%AF%86%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">调试口是最大也最常漏的洞：SWD 两根线即可读写全部闪存与全部外设寄存器。量产固件必须在选项字节里关掉调试口或设置读保护——但读保护等级与调试能力的取舍各家芯片不同，锁死之前先确认产线还能烧录。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按威胁模型排预算，而不是按功能堆砌。先回答「攻击者要什么」：要控制设备（僵尸网络），则口令治理与更新通道优先；要固件里的算法与数据，则读保护与镜像加密优先；要密钥本身，则安全元件优先。再按清单收缩攻击面：调试口锁定或读保护；引导加载器冻结（上一课的纪律在这里有了安全含义）；默认口令在首次配网时强制更换；通信全部走带认证的加密通道；日志与错误码不泄露内部结构。生命周期状态显式管理：开发态全开调试，量产态上锁，退役态销毁密钥——三个态的转变用 OTP 单向阀实现，只进不退。</p><p><span class="marginnote">「成本高于价值」给个数量感：一台 50 元的摄像头，若调试口忘了锁，一根十几元的 SWD 线几分钟就能抄走全部固件；若读保护与验签到位，提取密钥要动用千元级的实验室设备与数天工时。防守不需要「攻不破」，只需要让这条路不划算。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>安全的机制内核是<strong>锚点的不可改性</strong>：整个链条的安全性都压在根公钥那一小块存储上，ROM 与 OTP 的意义就是把「改写它」从软件问题抬升到开盖、聚焦离子束的物理问题——攻击成本由这里决定。验签先于执行是第二个不变量：任何代码只有通过验证才获得控制权，顺序反了，漏洞在验证完成前就已生效。至于加密与签名的关系，机密性防「读走」，真实性防「换掉」，两者独立：加密但不验签的固件通道，攻击者虽看不懂也能整包替换——完整性必须由带密钥的认证保证，AEAD 内部机制主干课已讲透，不重写。</p>',6)),(e(),r(o,null,{default:a(()=>[s(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ATT%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E7%9B%AF%E4%B8%8A%E5%9B%BA%E4%BB%B6%E9%80%9A%E9%81%93%22%5D%20--%3E%20Q1%7B%22%E4%BB%96%E6%83%B3%E8%AF%BB%E8%B5%B0%E5%86%85%E5%AE%B9%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E9%80%9A%E9%81%93%E6%9C%AA%E5%8A%A0%E5%AF%86%22%7C%20LEAK%5B%22%E7%AE%97%E6%B3%95%E4%B8%8E%E6%95%B0%E6%8D%AE%E6%B3%84%E9%9C%B2%22%5D%0A%20%20Q1%20--%3E%7C%22%E9%80%9A%E9%81%93%E5%8A%A0%E5%AF%86%22%7C%20SAFE1%5B%22%E8%AF%BB%E4%B8%8D%E5%88%B0%E6%98%8E%E6%96%87%22%5D%0A%20%20ATT%20--%3E%20Q2%7B%22%E4%BB%96%E6%83%B3%E6%8D%A2%E6%8E%89%E5%9B%BA%E4%BB%B6%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E9%80%9A%E9%81%93%E9%AA%8C%E7%AD%BE%22%7C%20SAFE2%5B%22%E7%AD%BE%E5%90%8D%E4%B8%8D%E7%AC%A6%EF%BC%8C%E6%95%B4%E5%8C%85%E6%8B%92%E7%BB%9D%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%8F%AA%E5%8A%A0%E5%AF%86%E4%B8%8D%E9%AA%8C%E7%AD%BE%22%7C%20HIT%5B%22%E7%9C%8B%E4%B8%8D%E6%87%82%E4%B9%9F%E8%83%BD%E6%95%B4%E5%8C%85%E6%9B%BF%E6%8D%A2%EF%BC%9A%E4%B8%AD%E6%8B%9B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">初学者容易以为「加密了就安全」；加密只防「读走」，不防「换掉」——没有验签的加密通道，攻击者把整包换成自己构造的密文，设备照样解密执行。机密性与真实性是两把独立的锁，缺一把门就没锁上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三块。形式化认证（Common Criteria、FIPS）是流程与评估体系，不是工程本身；侧信道与故障注入——差分功耗分析、电压毛刺跳过验签——是真实威胁，但属于芯片级对抗，MCU 工程师能做的是选带抗性的器件、不在同一条电源轨上跑敏感操作；协议密码学的内部在主干课 AEAD 一课已展开。也要承认物理安全的极限：攻击者无限期持有设备并动用实验室级设备，多数 MCU 终会被攻破；工程目标是把这条路径的成本抬到高于收益，并把最敏感的部分交给专门的硬件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物理可及改写威胁模型：调试口、闪存夹取、明文总线都是第一跳，口令治理是最便宜的补丁。</li><li>信任链从不可改写的 ROM 根公钥出发逐级验签，验签先于执行是顺序不变量。</li><li>密钥按预算安家：OTP、TrustZone 隔离、外挂安全元件，三档对应三种攻击成本。</li><li>加密防读走、认证防换掉，二者独立；镜像通道必须验签，否则 OTA 就是后门。</li><li>出处：NIST SP 800-193；UEFI 安全启动与 MCU 安全启动实践；据本栏 secure-boot-chain、aead-gcm-internals 两课口径整理。</li></ul>',5))])}const u=i(d,[["render",p]]);export{_ as __pageData,u as default};
